var builder = WebApplication.CreateBuilder(args);

builder.Services.AddScoped<IOrderService, OrderService>();
builder.Services.AddSingleton<IEmailSender, SmtpEmailSender>();

var app = builder.Build();

app.MapPost("/orders", async (CreateOrder request, IOrderService orders) =>
{
    var id = await orders.CreateAsync(request);
    return Results.Created($"/orders/{id}", new { id });
});

app.Run();

public interface IOrderService
{
    Task<Guid> CreateAsync(CreateOrder request);
}

// C# 12 primary constructor: the container supplies IEmailSender.
public sealed class OrderService(IEmailSender email) : IOrderService
{
    public async Task<Guid> CreateAsync(CreateOrder request)
    {
        var id = Guid.CreateVersion7();
        await email.SendAsync(request.CustomerEmail, "Order received", $"Your order {id} is confirmed.");
        return id;
    }
}

